function completedSet(){return new Set(appState?.profile?.completed||[])}
function chapterUnlocked(i){const chapter=appState?.curriculum?.[i];return !!chapter&&(chapter.prerequisites||[]).every(id=>{const prerequisite=appState.curriculum.find(c=>c.id===id);return prerequisite&&completedSet().has(prerequisite.tasks.at(-1).id)})}
