async function renderWorkshop(){const data=await fetch('/api/projects?profile_id='+encodeURIComponent(profileId)).then(r=>r.json());if(data.error)return toast(data.error);projectCatalog=data.projects;projectSaves=data.saves;const savedIncomplete=projectCatalog.find(p=>projectSaves[p.id]&&!projectSaves[p.id].completed);if(!projectCatalog.some(p=>p.id===selectedProjectId))selectedProjectId=savedIncomplete?.id||projectCatalog[0]?.id;const project=projectCatalog.find(p=>p.id===selectedProjectId);if(projectEditor){projectEditor.dispose();projectEditor=null}if(!project)return;const saved=projectSaves[project.id];$('#view-workshop').innerHTML=`<span class="eyebrow">⚒ ${tr('workshop')}</span><h1 class="view-title">${tr('workshop')}</h1><p class="view-lead">${tr('workshopLead')}</p><div class="workshop-grid"><aside class="project-list">${projectCatalog.map((p,i)=>`<button class="project-card ${project.id===p.id?'selected':''}" data-project="${p.id}"><span class="project-icon">${projectSaves[p.id]?.completed?'✅':(['🐾','🧮','🐟','🏠','📒','🔁','🏦','🔢'][i]||'🧩')}</span><span><b>${esc(tx(p.title))}</b><small><span class="project-stars" aria-label="${p.difficulty||1}/3">${'★'.repeat(p.difficulty||1)}${'☆'.repeat(3-(p.difficulty||1))}</span> · +${p.xp} XP${projectSaves[p.id]?.completed?' · ✓':''}</small></span></button>`).join('')}</aside><section class="project-work"><div class="panel"><span class="eyebrow">${projectSaves[project.id]?.completed?'✓ '+(L('ui.app.completed')):`+${project.xp} XP`}</span><h2>${esc(tx(project.title))}</h2>${(project.concepts||[]).length?`<div class="project-concepts">${project.concepts.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<p class="view-lead project-desc">${inlineCodeHtml(tx(project.description))}</p>${projectSteps(project)}${taskExample({kind:'code',tests:project.tests})}<div class="tip">${L('ui.app.projectAssessment',{tests:project.tests.length,requirements:project.requires.join(', ')})}</div></div><div class="editor-box" style="margin-top:12px"><div class="editor-top"><span>📄 project.cpp · Monaco</span><div class="editor-tools"><button id="project-save">💾 ${tr('saveDraft')}</button></div></div><div id="project-monaco" class="monaco-host"></div><label class="project-input-label"><span>⌨ ${L('ui.app.programInput')}</span><textarea id="project-input" class="answer-input" rows="${Math.min(5,String(project.tests[0].input).split('\n').length)}" spellcheck="false">${esc(project.tests[0].input)}</textarea></label><div class="console" id="project-console">${tr('output')}</div><div class="editor-actions"><button class="secondary" id="project-run">${tr('run')}</button><button class="primary" id="project-submit">${tr('projectSubmit')}</button></div></div><div id="project-result"></div></section></div>`;$$('.project-card').forEach(b=>b.onclick=()=>{selectedProjectId=b.dataset.project;renderWorkshop()});window.MonacoReady.then(monaco=>{const host=$('#project-monaco');if(!host)return;projectEditor=monaco.editor.create(host,{value:saved?.code||project.starter,language:'cpp',theme:'vs-dark',automaticLayout:true,fontSize:12,fontFamily:'Consolas, monospace',minimap:{enabled:false},scrollBeyondLastLine:false,wordWrap:'on',tabSize:4,wordBasedSuggestions:'off',snippetSuggestions:'top',suggest:{showWords:false}});let timer;projectEditor.onDidChangeModelContent(()=>{clearTimeout(timer);timer=setTimeout(()=>api('/api/project/save',{project_id:project.id,code:projectEditor.getValue()}),1000)});projectEditor.addCommand(monaco.KeyMod.CtrlCmd|monaco.KeyCode.KeyS,()=>saveProject())});$('#project-save').onclick=saveProject;$('#project-run').onclick=runProject;$('#project-submit').onclick=submitProject}
async function saveProject(){if(!projectEditor)return;const r=await api('/api/project/save',{project_id:selectedProjectId,code:projectEditor.getValue()});if(r.error)return toast(r.error);toast(L('ui.app.draftSaved'),true)}
