async function submitProject(){const code=projectEditor?.getValue()||'';const btn=$('#project-submit');if(btn)btn.disabled=true;const el=$('#project-result');el.innerHTML=`<div class="tip">${esc(tr('runRunning'))}</div>`;const r=await api('/api/project/submit',{project_id:selectedProjectId,code});if(btn)btn.disabled=false;if(r.error){el.innerHTML=`<div class="tip error">${esc(r.error)}</div>`;return}const fail=(r.checks||[]).find(x=>!x.passed);const rows=(r.checks||[]).map(x=>`<li class="${x.passed?'ok':'bad'}">${x.passed?'✓':'✕'} ${esc(x.name)}</li>`).join('');const missing=(r.missing||[]).length?`<p>${esc(lang==='ru'?'В коде не найдено:':'Kodda bulunamayan:')} ${r.missing.map(x=>`<code>${esc(x)}</code>`).join(' ')}</p>`:'';const diff=fail?`<div class="task-example-grid"><div><small>${esc(lang==='ru'?'Ожидалось':'Beklenen')}</small><pre>${esc(fail.expected)}</pre></div><div><small>${esc(lang==='ru'?'Твой вывод':'Senin çıktın')}</small><pre>${esc(fail.actual||fail.error||'')}</pre></div></div>`:'';el.innerHTML=`<div class="project-verdict ${r.ok?'ok':'bad'}"><b>${r.ok?`${L('ui.app.projectPassed')} ${r.xp?`+${r.xp} XP`:L('ui.app.xpAlreadyEarned')}`:L('ui.app.projectFailed')}</b><ul>${rows}</ul>${missing}${diff}</div>`;await refresh();projectSaves[selectedProjectId]={...(projectSaves[selectedProjectId]||{}),code,completed:r.ok||projectSaves[selectedProjectId]?.completed,score:r.score};if(r.ok){$$('.project-card.selected small').forEach(x=>{if(!x.textContent.includes('✓'))x.textContent+=' · ✓'})}}
