function renderLessonIntro(){const c=appState.curriculum[currentChapter],guide=c.guide?.[lang]||c.guide?.tr||[];$('#view-lesson').innerHTML=`<div class="section-head lesson-top"><div><span class="eyebrow">🐾 ${tr('chapter')} ${String(c.number).padStart(2,'0')} · ${tr('lesson')}</span><h1 class="view-title">${esc(tx(c.title))}</h1></div><span class="lesson-duration">${guide.length} ${L('motion.lessonParts')} · ${c.tasks.length} ${L('motion.missionCount')}</span></div><div class="lesson-intro-grid"><article class="lesson-intro-card"><span class="eyebrow">${ex('learnTitle')}</span><p class="lesson-overview">${esc(tx(c.lesson))}</p><div class="lesson-concepts">${guide.map(([title,body,code],i)=>`<section class="lesson-concept ${code&&code.includes('✗')?'concept-warn':''} ${!code&&i===guide.length-1&&guide.length>2?'concept-check':''}"><div class="concept-mark">${String(i+1).padStart(2,'0')}</div><div><h2>${esc(title)}</h2><p>${esc(body)}</p>${code?`<pre class="code-block concept-code">${codeMarks(code)}</pre>`:''}</div></section>`).join('')}</div><h2 class="lesson-section-title">${ex('practice')}</h2><pre class="code-block lesson-example">${esc(c.example)}</pre><button class="primary lesson-start" id="begin-missions">${ex('beginMissions')} →</button></article><aside class="lesson-cat-card"><img src="/assets/cat-companion.png" alt="${ex('companion')}" class="lesson-cat-image"><div class="cat-caption">😸 ${ex('companion')}</div><div class="tip">🐾 ${ex('learnLead')}</div></aside></div>`;$('#begin-missions').onclick=()=>{lessonMode=false;const idx=currentOpenTask(currentChapter);if(idx>=0)currentTask=idx;renderLesson()}}
