function showHint(level){const task=appState.curriculum[currentChapter].tasks[currentTask],key=`${task.id}-${level}`;if(level>0&&!hintsUsed.has(`${task.id}-${level-1}`))return toast(L('ui.app.hintOrder'));if(hintsUsed.has(key))return;hintsUsed.add(key);const fallback=L('ui.app.hintFallback');const box=$('#hint-box');box.textContent=`${tr('hint')} ${level+1}: ${task.hints?.[lang]?.[level]||fallback}`;box.classList.remove('hidden');const next=$(`.hint-btn[data-hint="${level+1}"]`);if(next)next.disabled=false;toast(tr('hintUsed'))}
function runResultPanel(result){const compileLabel=result.compile_ok?tr('runCompileOk'):tr('runCompileFailed');const compileClass=result.compile_ok?'success':'error';const line=(label,value)=>`<section class="run-output-block"><b>${label}</b><pre>${esc(value||tr('runNoOutput'))}</pre></section>`;return `<div class="run-report"><div class="run-summary ${compileClass}"><span>${tr('runCompileStatus')}: ${compileLabel}</span><span>${tr('runExitCode')}: ${result.exit_code??'—'}</span><span>${tr('runDuration')}: ${result.elapsed_ms??0} ms</span></div>${result.error?`<div class="run-error-detail">${esc(result.error)}</div>`:''}${line(tr('runStdout'),result.stdout||result.output)}${line(tr('runStderr'),result.stderr)}${result.compile_output?line(tr('runCompilerOutput'),result.compile_output):''}</div>`}
