async function submitTask(){const task=appState.curriculum[currentChapter].tasks[currentTask],answer=$('#answer-input')?$('#answer-input').value:monacoEditor?.getValue()||'';if(!answer.trim()){toast(L('ui.app.answerRequired'));return}const result=await api('/api/submit',{task_id:task.id,answer,hint_used:[0,1,2].some(i=>hintsUsed.has(`${task.id}-${i}`))});const spot=$('#task-result');if(result.correct){const tests=result.tests?.map(t=>`✓ ${esc(t.name)}`).join(' · ')||'';spot.innerHTML=`<div class="tip success">✓ ${tr('correct')} ${result.xp?`+${result.xp} XP`:''}${result.daily_bonus?` · +${result.daily_bonus} ${L('ui.app.dailyBonus')}`:''}${tests?`<br>${tests}`:''}${result.already_done?' · '+(L('ui.app.taskAlreadyDone')) :''}</div>`;await refresh();const wasLast=currentTask===appState.curriculum[currentChapter].tasks.length-1;setTimeout(()=>{if(wasLast&&chapterDone(currentChapter)&&currentChapter<appState.curriculum.length-1){toast(L('ui.app.bossDefeated'),true);openChapter(currentChapter+1)}else{const nxt=appState.curriculum[currentChapter].tasks.findIndex((t,i)=>i>currentTask&&!completedSet().has(t.id));if(nxt>=0){currentTask=nxt;renderLesson();document.querySelector('#task-title')?.focus({preventScroll:false})}}},850)}else{let extra=result.result?.error||result.result?.output||'';if(result.result?.criteria)extra+=`\n${L('ui.app.conceptChecked')}: ${result.result.criteria}`;if(result.result?.missing)extra+=`\n${L('ui.app.missingCriteria')}: ${result.result.missing.join(', ')}`;if(result.result?.checks){const failed=result.result.checks.filter(t=>!t.passed);if(failed.length)extra+=`\n${failed.map(t=>t.kind==='concept'?`✕ ${t.name}`:`${t.name}: ${L('ui.app.expected')} ${t.expected}, ${L('ui.app.received')} ${t.actual}`).join('\n')}`}spot.innerHTML=`<div class="tip error">✕ ${tr('wrong')}${extra?`<pre class="code-block">${esc(extra)}</pre>`:''}</div>`}}
