function renderMap(){const done=completedSet();$('#view-map').innerHTML=`<span class="eyebrow">⌖ ${tr('journey')} · ${tr('mapPath')}</span><h1 class="view-title">${tr('knowledgeMap')}</h1><p class="view-lead">${tr('mapLead')} ${tr('progress')}: ${done.size}/${appState.profile.total_tasks}.</p><div class="knowledge-map">${appState.curriculum.map((c,i)=>{const n=c.tasks.filter(t=>done.has(t.id)).length,pct=Math.round(n/c.tasks.length*100),unlocked=chapterUnlocked(i),complete=chapterDone(i),needs=(c.prerequisites||[]).map(id=>appState.curriculum.find(x=>x.id===id)).filter(Boolean);return `<article class="map-card knowledge-node ${unlocked?'':'locked'} ${complete?'mastered':''}" data-chapter="${i}"><div class="map-number">${unlocked?chapterIcon(i):chapterIcon(-1)}</div><div class="knowledge-node-copy"><div class="knowledge-node-status">${complete?'✓ '+tr('mapMastered'):unlocked?tr('mapReady'):tr('mapLocked')}</div><h3><button type="button" class="map-open" data-chapter="${i}">${String(i+1).padStart(2,'0')} · ${esc(tx(c.title))}</button></h3><p>${esc(tx(c.lesson))}</p><div class="knowledge-requires"><small>${tr('mapRequires')}:</small>${needs.length?needs.map(x=>`<button class="knowledge-prereq" data-chapter="${x.number-1}" ${chapterUnlocked(x.number-1)?'':'disabled'}>↗ ${esc(tx(x.title))}</button>`).join(''):`<span>${tr('mapStart')}</span>`}</div><div class="map-progress"><small>${n}/${c.tasks.length} ${tr('done')}</small><div class="progress-track" style="margin-top:7px"><span style="width:${pct}%"></span></div></div></div></article>`}).join('')}</div><div class="panel" style="margin-top:16px"><h3>${tr('leaderboard')}</h3><div id="leaderboard"></div></div>`;$$('.map-card').forEach(el=>el.onclick=()=>openChapter(+el.dataset.chapter));$$('.knowledge-prereq').forEach(el=>el.onclick=e=>{e.stopPropagation();openChapter(+el.dataset.chapter)});loadLeaderboard()}
async function renderJournal(){if(!appState||!profileId)return;const host=$('#view-journal');host.innerHTML=`<div class="journal-loading">${L('ui.app.journalLoading')}</div>`;const data=await fetch('/api/journal?profile_id='+encodeURIComponent(profileId)).then(r=>r.json());if(data.error){host.innerHTML=`<div class="tip error">${esc(data.error)}</div>`;return}const topics=data.topics||[],recent=data.recent||[],daily=data.daily||[],maxDay=Math.max(1,...daily.map(x=>x.attempts));const taskById=new Map(appState.curriculum.flatMap(c=>c.tasks.map(t=>[t.id,t])));const errorLabel={requirement:'journalRequirement',compile:'journalCompile',runtime:'journalRuntime',output:'journalOutput',wrong_answer:'journalAnswer'};host.innerHTML=`<span class="eyebrow">✦ ${tr('journal')}</span><h1 class="view-title">${tr('journal')}</h1><p class="view-lead">${tr('journalLead')}</p><div class="journal-stats"><article class="stat-card"><div class="stat-head">${tr('journalAttempts')}</div><div class="stat-number">${data.attempts||0}</div></article><article class="stat-card"><div class="stat-head">${tr('journalAccuracy')}</div><div class="stat-number">${data.attempts?Math.round(data.correct/data.attempts*100):0}%</div></article><article class="stat-card"><div class="stat-head">${tr('journalCompleted')}</div><div class="stat-number">${data.completed||0}<span class="journal-total"> / ${data.total_tasks||0}</span></div></article></div>${!recent.length?`<div class="panel journal-empty">🐈‍⬛<p>${tr('journalEmpty')}</p></div>`:''}<div class="journal-columns"><section class="panel"><h2>${tr('journalNext')}</h2><p class="journal-note">${tr('journalPrediction')}</p>${(data.suggestions||[]).map(s=>{const c=appState.curriculum.find(x=>x.id===s.chapter_id);return c?`<button class="journal-suggestion" data-chapter="${c.number-1}"><span>${s.kind==='review'?'↻':'➜'}</span><span><b>${esc(tx(c.title))}</b><small>${s.kind==='review'?tr('journalReview'):tr('journalContinue')}${s.accuracy!==null&&s.accuracy!==undefined?` · ${Math.round(s.accuracy*100)}%`:''}</small></span></button>`:''}).join('')||`<p class="journal-note">${tr('journalNoWeak')}</p>`}<h3 class="journal-subhead">${tr('journalWeak')}</h3>${(data.weak_topics||[]).map(t=>`<div class="weak-row"><b>${esc(tx(t.title))}</b><span>${Math.round(t.accuracy*100)}% · ${t.attempts} ${tr('journalAttempts').toLowerCase()}</span></div>`).join('')||`<p class="journal-note">${tr('journalNoWeak')}</p>`}</section><section class="panel"><h2>${tr('journalDays')}</h2><div class="journal-days">${daily.slice().reverse().map(d=>`<div class="journal-day" title="${esc(d.day)} · ${d.attempts}"><span style="height:${Math.max(8,Math.round(d.attempts/maxDay*100))}%"></span><small>${esc(d.day.slice(5))}</small></div>`).join('')||`<p class="journal-note">—</p>`}</div><h3 class="journal-subhead">${tr('journalRecent')}</h3><div class="journal-recent">${recent.slice(0,12).map(e=>{const task=taskById.get(e.task_id);const chapter=appState.curriculum.find(c=>c.id===e.chapter_id);return `<div class="journal-event ${e.correct?'passed':'failed'}"><i>${e.correct?'✓':'!'}</i><span><b>${esc(tx(task?.title)||e.task_id)}</b><small>${esc(tx(chapter?.title))} · ${e.correct?tr('journalRight'):tr('journalWrong')}${e.error_kind?` · ${tr(errorLabel[e.error_kind]||'journalError')}`:''}${e.hint_used?` · ${tr('hint')}`:''}</small></span><time>${esc((e.created_at||'').slice(0,16))}</time></div>`}).join('')||`<p class="journal-note">${tr('journalEmpty')}</p>`}</div></section></div><section class="panel journal-topics"><h2>${tr('journalTopics')}</h2><div class="journal-topic-list">${topics.map(t=>`<button class="journal-topic" data-chapter="${t.number-1}"><span class="journal-topic-name"><b>${esc(tx(t.title))}</b><small>${t.completed}/${t.total} ${tr('done')} · ${t.attempts} ${tr('journalAttempts').toLowerCase()}</small></span><span class="journal-topic-meter"><i style="width:${t.accuracy===null?0:Math.round(t.accuracy*100)}%"></i></span><strong>${t.accuracy===null?'—':Math.round(t.accuracy*100)+'%'}</strong></button>`).join('')}</div></section>`;$$('.journal-suggestion,.journal-topic').forEach(b=>b.onclick=()=>openChapter(+b.dataset.chapter))}
function qualityDraft(key){return localStorage.getItem(`cpp-adventure-quality-${profileId}-${key}`)||''}
function qualityReport(data){const m=data.metrics||{};return `<div class="quality-result"><div class="quality-score"><b>${data.score}</b><span>/100 · ${tr('qualityScore')}</span></div><div class="quality-metrics"><span>${m.characters||0} ${tr('characters')}</span><span>${m.lines||0} ${tr('lines')}</span><span>${m.functions||0} ${tr('functions')}</span><span>${m.branch_points||0} ${tr('branches')}</span></div><p class="quality-footnote">${tr('analysisBasis')}</p><h3>${tr('qualityIssues')}</h3>${data.issues?.length?`<ul class="quality-issues">${data.issues.map(x=>`<li class="severity-${esc(x.severity)}">${esc(x.message)}</li>`).join('')}</ul>`:`<p class="quality-empty">${tr('qualityEmpty')}</p>`}</div>`}
const LAB_NAMES={variables:'labVariables',conditions:'labConditions',loops:'labLoops',functions:'labFunctions',arrays:'labArrays',pointers:'labPointers',memory:'labMemoryTitle',oop:'labOop',algorithms:'labAlgorithms'};
const LAB_FIELDS={variables:[['start','labStartValue','number',3],['add','labAddition','number',4]],conditions:[['score','labScoreValue','number',72],['threshold','labThreshold','number',50]],loops:[['start','labLoopStart','number',1],['end','labLoopEnd','number',5],['step','labLoopStep','number',1]],functions:[['param','labParameter','number',6],['operation','labOperation','select',[['double','labDouble'],['square','labSquare'],['add3','labAddThree']]]],arrays:[['values','labArrayValues','text','3,5,8'],['index','labIndex','number',1]],pointers:[['a','labValueA','number',10],['b','labValueB','number',20],['target','labTarget','select',[['a','labTargetA'],['b','labTargetB']]]],memory:[['scenario','labScenario','select',[['freed','labFreed'],['leak','labLeak'],['dangling','labDangling']]]],oop:[['name','labName','text','Luna'],['level','labLevel','number',1]],algorithms:[['values','labArrayValues','text','5,2,4,1'],['algorithm','labAlgorithmChoice','select',[['bubble_sort','labBubbleSort'],['linear_search','labLinearSearch']]],['target','labSearchTarget','number',4]]};
function labStoredValues(){const defaults={};for(const [key,label,type,value]of LAB_FIELDS[activeLab])defaults[key]=type==='select'?value[0][0]:value;try{return{...defaults,...JSON.parse(localStorage.getItem(`cpp-adventure-lab-${profileId}-${activeLab}`)||'{}')}}catch{return defaults}}
function labFieldMarkup([key,label,type,value],values){const v=values[key]??(type==='select'?value[0][0]:value);if(type==='select')return `<label class="lab-field">${tr(label)}<select data-lab-field="${key}">${value.map(([option,text])=>`<option value="${option}" ${v===option?'selected':''}>${tr(text)}</option>`).join('')}</select></label>`;return `<label class="lab-field">${tr(label)}<input data-lab-field="${key}" type="${type==='number'?'number':'text'}" value="${esc(v)}" ${type==='number'?'min="-1000" max="1000"':''}></label>`}
async function renderLabs(){if(labTimer){clearInterval(labTimer);labTimer=null}const host=$('#view-labs');host.innerHTML=`<div class="journal-loading">${L('ui.app.labsLoading')}</div>`;const data=await fetch('/api/labs?profile_id='+encodeURIComponent(profileId)).then(r=>r.json());if(data.error){host.innerHTML=`<div class="tip error">${esc(data.error)}</div>`;return}if(!data.labs.some(l=>l.id===activeLab))activeLab='variables';const values=labStoredValues();host.innerHTML=`<span class="eyebrow">▦ ${tr('labsNav')}</span><h1 class="view-title">${tr('labsTitle')}</h1><p class="view-lead">${tr('labsLead')}</p><div class="lab-picker">${data.labs.map((lab,i)=>`<button class="lab-choice ${lab.id===activeLab?'selected':''} ${lab.completed?'complete':''}" data-lab="${lab.id}"><span>${chapterIcon([1,4,5,6,7,9,15,11,12][i]??0)}</span><b>${esc(tx(lab.title))}</b><small>${lab.completed?'✓ ':''}+${lab.xp} XP</small></button>`).join('')}</div><div class="lab-workspace"><section class="panel lab-controls"><h2>${tr('labInputs')}</h2><p class="lab-help">${tr(LAB_NAMES[activeLab])} · ${tr('labControls')}</p><div class="lab-fields">${LAB_FIELDS[activeLab].map(field=>labFieldMarkup(field,values)).join('')}</div><div class="lab-challenge"><b>${tr('labPredict')}</b><p id="lab-challenge-prompt"></p><input id="lab-answer" class="answer-input" autocomplete="off"><button id="lab-submit" class="primary">${tr('labSubmit')}</button><div id="lab-award"></div></div></section><section class="panel lab-visual"><div class="lab-visual-head"><div><h2>${tr('labView')}</h2><small id="lab-step-count"></small></div><span class="lab-step-number" id="lab-step-number"></span></div><div class="lab-steps"><div class="lab-progress"><i id="lab-progress"></i></div><p id="lab-step-text"></p></div><h3 class="lab-memory-title">${tr('labMemory')}</h3><div id="lab-memory-grid" class="lab-memory-grid"></div><div id="lab-final-output" class="lab-final-output hidden"></div><div class="lab-controls-row"><button class="secondary" id="lab-reset">↺ ${tr('labReset')}</button><button class="secondary" id="lab-back">‹ ${tr('labBackward')}</button><button class="primary" id="lab-play">▶ ${tr('labPlay')}</button><button class="secondary" id="lab-next">${tr('labForward')} ›</button></div><label class="lab-speed">${tr('labSpeed')} <input type="range" id="lab-speed" min="400" max="2200" step="100" value="${labSpeed}"><span id="lab-speed-value">${(2200/labSpeed).toFixed(1)}×</span></label></section></div>`;$$('.lab-choice').forEach(b=>b.onclick=()=>{if(b.dataset.lab!==activeLab){activeLab=b.dataset.lab;labSimulation=null;labStepIndex=0;renderLabs()}});$$('[data-lab-field]').forEach(el=>el.onchange=async()=>{const updated=labStoredValues();updated[el.dataset.labField]=el.value;localStorage.setItem(`cpp-adventure-lab-${profileId}-${activeLab}`,JSON.stringify(updated));await simulateCurrentLab()});$('#lab-speed').oninput=e=>{labSpeed=+e.target.value;$('#lab-speed-value').textContent=`${(2200/labSpeed).toFixed(1)}×`;if(labTimer){clearInterval(labTimer);startLabPlayback()}};$('#lab-reset').onclick=()=>{pauseLabPlayback();labStepIndex=0;renderLabBoard()};$('#lab-back').onclick=()=>{labStepIndex=Math.max(0,labStepIndex-1);renderLabBoard()};$('#lab-next').onclick=()=>{labStepIndex=Math.min((labSimulation?.steps.length||1)-1,labStepIndex+1);renderLabBoard()};$('#lab-play').onclick=()=>labTimer?pauseLabPlayback():startLabPlayback();$('#lab-submit').onclick=submitLabPrediction;$('#lab-challenge-prompt').textContent='';await simulateCurrentLab()}
function currentLabValues(){const values={};$$('[data-lab-field]').forEach(el=>values[el.dataset.labField]=el.value);return values}
async function simulateCurrentLab(){const result=await api('/api/labs/simulate',{lab_id:activeLab,values:currentLabValues()});if(result.error){toast(result.error);return}labSimulation=result;labStepIndex=0;$('#lab-challenge-prompt').textContent=result.challenge.prompt;$('#lab-answer').value='';$('#lab-award').textContent='';renderLabBoard()}
function renderLabBoard(){if(!labSimulation)return;const steps=labSimulation.steps,index=Math.max(0,Math.min(labStepIndex,steps.length-1)),step=steps[index];labStepIndex=index;$('#lab-step-count').textContent=`${tr('labStep')} ${index+1} / ${steps.length}`;$('#lab-step-number').textContent=String(index+1).padStart(2,'0');$('#lab-step-text').textContent=step.text;$('#lab-progress').style.width=`${steps.length>1?index/(steps.length-1)*100:100}%`;$('#lab-memory-grid').innerHTML=step.cells.map(cell=>`<article class="lab-memory-cell ${esc(cell.status||'')}"><small>${esc(cell.region)} · ${esc(cell.address)}</small><b>${esc(cell.name)}</b><span>${esc(cell.value)}</span><i>${esc(cell.type)}</i></article>`).join('')||'—';$('#lab-final-output').textContent=index===steps.length-1?labSimulation.final:'';$('#lab-final-output').classList.toggle('hidden',index!==steps.length-1);$('#lab-back').disabled=index===0;$('#lab-next').disabled=index===steps.length-1;$('#lab-play').textContent=labTimer?`⏸ ${tr('labPause')}`:`▶ ${tr('labPlay')}`}
function startLabPlayback(){if(!labSimulation)return;if(labStepIndex>=labSimulation.steps.length-1)labStepIndex=0;labTimer=setInterval(()=>{if(labStepIndex>=labSimulation.steps.length-1){pauseLabPlayback();return}labStepIndex++;renderLabBoard()},labSpeed);renderLabBoard()}
function pauseLabPlayback(){if(labTimer){clearInterval(labTimer);labTimer=null}renderLabBoard()}
async function submitLabPrediction(){const answer=$('#lab-answer').value,result=await api('/api/labs/submit',{lab_id:activeLab,values:currentLabValues(),answer}),spot=$('#lab-award');if(result.error){spot.innerHTML=`<div class="tip error">${esc(result.error)}</div>`;return}if(result.correct){spot.innerHTML=`<div class="tip success">✓ ${tr('labRight')} ${result.xp?`+${result.xp} XP`:tr('labAwarded')}</div>`;catReact('happy');await refresh();return}spot.innerHTML=`<div class="tip error">${tr('labWrong')}<br>${esc(result.hint||'')}</div>`;catReact('thinking')}
function renderQuality(){const host=$('#view-quality');host.innerHTML=`<span class="eyebrow">⌘ ${tr('qualityNav')}</span><h1 class="view-title">${tr('qualityTitle')}</h1><p class="view-lead">${tr('qualityLead')}</p><div class="quality-tabs"><button class="quality-tab ${qualityTab==='quality'?'active':''}" data-tab="quality">${tr('qualityTab')}</button><button class="quality-tab ${qualityTab==='golf'?'active':''}" data-tab="golf">${tr('golfTab')}</button></div><section id="quality-pane" class="quality-pane ${qualityTab==='quality'?'':'hidden'}"><label class="quality-label">${tr('sourceCode')}<textarea id="quality-code" class="cpp-textarea" spellcheck="false" placeholder="#include <iostream>\nint main() {\n    // Kodunu buraya yaz\n    return 0;\n}">${esc(qualityDraft('single'))}</textarea></label><button class="primary quality-action" id="quality-analyze">⌕ ${tr('analyzeQuality')}</button><div id="quality-result"></div></section><section id="golf-pane" class="quality-pane ${qualityTab==='golf'?'':'hidden'}"><div class="golf-editors"><label class="quality-label">${tr('solutionA')}<textarea id="golf-a" class="cpp-textarea" spellcheck="false" placeholder="#include <iostream>\nint main() {\n    // Çözüm A\n    return 0;\n}">${esc(qualityDraft('a'))}</textarea></label><label class="quality-label">${tr('solutionB')}<textarea id="golf-b" class="cpp-textarea" spellcheck="false" placeholder="#include <iostream>\nint main() {\n    // Çözüm B\n    return 0;\n}">${esc(qualityDraft('b'))}</textarea></label></div><label class="quality-label">${tr('stdinSample')}<input id="golf-input" class="answer-input" value="${esc(qualityDraft('input'))}"></label><button class="primary quality-action" id="golf-compare">⚖ ${tr('compareSolutions')}</button><div id="golf-result"></div></section>`;$$('.quality-tab').forEach(b=>b.onclick=()=>{qualityTab=b.dataset.tab;renderQuality()});[['quality-code','single'],['golf-a','a'],['golf-b','b'],['golf-input','input']].forEach(([id,key])=>{const el=$('#'+id);el.oninput=()=>localStorage.setItem(`cpp-adventure-quality-${profileId}-${key}`,el.value)});$('#quality-analyze').onclick=async()=>{const code=$('#quality-code').value,spot=$('#quality-result');spot.innerHTML=`<div class="journal-loading">${L('ui.app.codeDiagnosing')}</div>`;const result=await api('/api/quality/analyze',{code});spot.innerHTML=result.error?`<div class="tip error">${esc(result.error)}</div>`:qualityReport(result)};$('#golf-compare').onclick=async()=>{const a=$('#golf-a').value,b=$('#golf-b').value,spot=$('#golf-result');if(!a.trim()||!b.trim()){spot.innerHTML=`<div class="tip error">${tr('golfEmpty')}</div>`;return}spot.innerHTML=`<div class="journal-loading">${L('ui.app.golfCompiling')}</div>`;const result=await api('/api/code-golf/compare',{code_a:a,code_b:b,input:$('#golf-input').value});if(result.error){spot.innerHTML=`<div class="tip error">${esc(result.error)}</div>`;return}spot.innerHTML=`<div class="tip ${result.equivalent_output?'success':'error'}">${result.equivalent_output?tr('golfSame'):tr('golfDifferent')}</div><p class="quality-footnote">${tr('complexityNote')}</p><div class="golf-results">${result.variants.map((v,i)=>`<article class="panel golf-result-card"><h3>${i===0?tr('solutionA'):tr('solutionB')}</h3><div class="golf-metrics"><span>${v.characters} ${tr('characters')}</span><span>${v.lines} ${tr('lines')}</span><span>${v.elapsed_ms} ms · ${tr('compileRun')}</span></div><h4>${tr('output')}</h4><pre class="code-block">${esc(v.run.ok?v.run.output:(v.run.error||v.run.stderr||'Error'))}</pre>${qualityReport(v.quality)}</article>`).join('')}</div>`}}
async function loadLeaderboard(){const el=$('#leaderboard');if(!el)return;try{const res=await fetch('/api/leaderboard').then(r=>r.json());el.innerHTML=`<div style="display:grid;gap:7px">${res.leaderboard.map((u,i)=>`<div class="continue-row" style="padding:7px 2px;border-bottom:1px solid #242835"><span style="width:23px;color:#aaa">${i+1}.</span>${avatarHtml(u.avatar,'avatar-inline')}<b style="flex:1;font-size:11px">${esc(u.name)}${u.id===profileId?' · '+(L('ui.app.you')):''}</b><span class="quest-xp">${u.xp} XP</span></div>`).join('')||'—'}</div>`}catch{}}
function renderAchievements(){$('#view-achievements').innerHTML=`<span class="eyebrow">✧ ${tr('badges')}</span><h1 class="view-title">${tr('badges')}</h1><p class="view-lead">${appState.profile.achievements.length} / ${BADGES.length}</p><div class="achievement-grid">${BADGES.map(([id,emoji,title,desc])=>{const got=appState.profile.achievements.includes(id);return `<article class="achievement-card ${got?'':'locked'}"><span class="big">${emoji}</span><h3>${tr(title)}</h3><p>${tr(desc)}</p><p class="${got?'success':''}" style="margin-top:10px">${got?'✓ '+tr('earned'):tr('notEarned')}</p></article>`}).join('')}</div><div class="section-head"><div><h2>${tr('leaderboard')}</h2><p>${tr('local')}</p></div></div><div class="panel" id="leaderboard"></div>`;loadLeaderboard()}
async function refresh(){if(!profileId)return;const previous=appState?.profile?{id:String(appState.profile.id||profileId),level:Number(appState.profile.level||1)}:null;appState=await api('/api/state?profile_id='+encodeURIComponent(profileId));if(appState.error){profileId='';localStorage.removeItem('cpp-adventure-profile');return renderProfiles()}const nextLevel=Number(appState.profile.level||1);if(previous&&previous.id===String(appState.profile.id||profileId)&&nextLevel>previous.level)document.dispatchEvent(new CustomEvent('cpp-adventure-level-up',{detail:{profileId:profileId,level:nextLevel}}));renderSidebar();if(!$('#view-home').classList.contains('hidden'))renderHome();else if(!$('#view-map').classList.contains('hidden'))renderMap();else if(!$('#view-journal').classList.contains('hidden'))renderJournal();else if(!$('#view-achievements').classList.contains('hidden'))renderAchievements();else if(!$('#view-shop').classList.contains('hidden'))window.renderShop?.()}
function setLangButton(){document.documentElement.lang=lang;localStorage.setItem('cpp-adventure-language',lang);$('#lang-btn').textContent=lang==='tr'?L('ui.app.languageRussian'):L('ui.app.languageTurkish');window.CppSplash?.setLanguage(lang);if(!profileId)$('#rank').textContent=L('ui.app.rankBeginner');$$('[data-i]').forEach(el=>el.textContent=tr(el.dataset.i));$$('[data-i-title]').forEach(el=>el.title=tr(el.dataset.iTitle));$$('[data-i-aria]').forEach(el=>el.setAttribute('aria-label',tr(el.dataset.iAria)))}
async function changeLang(){lang=lang==='tr'?'ru':'tr';window.CppAdventureI18n.setLanguage(lang);setLangButton();if(profileId)await api('/api/settings',{lang});if(showingProfiles||!profileId){renderProfiles();document.dispatchEvent(new Event('cpp-adventure-language-changed'));return}await refresh();if(!$('#view-lesson').classList.contains('hidden'))renderLesson();if(!$('#view-shop').classList.contains('hidden'))renderShop();if(!$('#view-workshop').classList.contains('hidden'))renderWorkshop();if(!$('#view-settings').classList.contains('hidden'))renderSettings();if(!$('#view-journal').classList.contains('hidden'))renderJournal();if(!$('#view-quality').classList.contains('hidden'))renderQuality();if(!$('#view-labs').classList.contains('hidden'))renderLabs();document.dispatchEvent(new Event('cpp-adventure-language-changed'));}
async function loadProfiles(){const r=await fetch('/api/profiles').then(r=>r.json());profiles=r.profiles||[];return profiles}
async function renderSettings(){if(!profileId||!appState)return toast(L('ui.app.profileRequired'));$$('.view').forEach(v=>v.classList.add('hidden'));const view=$('#view-settings');view.classList.remove('hidden');$('#crumb-current').textContent=aiText('settings');view.innerHTML=`<div class="panel settings-loading">${L('ui.app.aiStatusLoading')}</div>`;let status=await fetch('/api/ai/status?profile_id='+encodeURIComponent(profileId)).then(r=>r.json()).catch(()=>({error:'offline'}));if(status.error)return view.innerHTML=`<div class="panel">${esc(status.error)}</div>`;const usages=status.usage||[];const totalIn=usages.reduce((n,u)=>n+u.input_tokens,0),totalOut=usages.reduce((n,u)=>n+u.output_tokens,0),requests=usages.reduce((n,u)=>n+u.requests,0),cost=usages.reduce((n,u)=>n+u.estimated_usd,0);view.innerHTML=`<span class="eyebrow">⚙ ${aiText('settings')}</span><h1 class="view-title">${aiText('settings')}</h1><p class="view-lead">${aiText('offlineDesc')}</p><div class="settings-grid"><section class="panel settings-panel"><h2>${aiText('provider')}</h2><label class="settings-select-label" for="ai-provider">${aiText('provider')}</label><select id="ai-provider" class="settings-select"><option value="groq">${aiText('groq')}</option><option value="claude">${aiText('claude')}</option><option value="offline">${aiText('offline')}</option><option value="ollama">${aiText('ollama')}</option><option value="openai">${aiText('openai')}</option><option value="off">${aiText('off')}</option></select><p class="setting-note">${aiText('sendPolicy')}</p><button class="primary" id="ai-settings-save">${aiText('saveSettings')}</button><div class="settings-status-list">${aiKeyRow('groq',status)}${aiKeyRow('claude',status)}<div><b>${aiText('offline')}</b><span class="status-ok">● ${aiText('configured')}</span><small>${aiText('offlineDesc')}</small></div><div><b>${aiText('openai')}</b><span class="${status.openai_configured?'status-ok':'status-warn'}">● ${status.openai_configured?aiText('configured'):aiText('missingKey')}</span><small>${aiText('model')}: ${esc(status.openai_model)} · ${aiText('keySafe')}</small></div><div><b>${aiText('ollama')}</b><span class="${status.ollama_models.length?'status-ok':'status-warn'}">● ${status.ollama_models.length?aiText('configured'):aiText('notInstalled')}</span><small>${aiText('model')}: ${esc(status.ollama_model)} · ${status.ollama_models.length?esc(status.ollama_models.join(', ')):aiText('localInstall')}</small></div></div></section><section class="panel settings-panel"><h2>${aiText('usage')}</h2><div class="usage-stat"><small>${aiText('tokens')}</small><b>${totalIn.toLocaleString()} / ${totalOut.toLocaleString()}</b></div><div class="usage-stat"><small>${aiText('requests')}</small><b>${requests}</b></div><div class="usage-stat"><small>${aiText('estimate')}</small><b>${cost?`$${cost.toFixed(4)}`:aiText('costUnknown')}</b></div><p class="setting-note">${L('ui.app.openaiUsageNote')}</p><div class="offline-banner">🐾 ${aiText('saved')}</div></section></div><button class="secondary" id="settings-home" style="margin-top:15px">← ${tr('home')}</button>`;$('#ai-provider').value=appState.profile.ai_provider||'offline';$('#ai-settings-save').onclick=async()=>{const r=await api('/api/settings',{ai_provider:$('#ai-provider').value});if(r.error)return toast(r.error);await refresh();toast(aiText('settingsSaved'),true);renderSettings()};$('#settings-home').onclick=()=>{renderHome();setView('home')};const saveAiKey=async(provider,key)=>{const r=await api('/api/ai/key',{provider,key});if(r.error)return toast(r.error);await refresh();toast(aiText(key?'keySaved':'keyRemoved'),true);renderSettings()};$$('[data-ai-key-save]').forEach(b=>b.onclick=()=>{const p=b.dataset.aiKeySave,input=$(`#${p}-key`),key=input.value.trim();if(!key)return input.focus();saveAiKey(p,key)});$$('[data-ai-key-remove]').forEach(b=>b.onclick=()=>saveAiKey(b.dataset.aiKeyRemove,''))}
function renderProfiles(){showingProfiles=true;const view=$('#view-home');$$('.view').forEach(v=>v.classList.add('hidden'));view.classList.remove('hidden');$('#crumb-current').textContent=tr('profile');loadProfiles().then(()=>{view.innerHTML=`<div class="hero" style="min-height:170px"><div class="hero-copy"><span class="eyebrow">🐾 ${tr('profile')}</span><h1>${tr('switch')}</h1><p>${tr('noProfiles')}</p></div><div class="hero-art">😺</div></div><div class="section-head"><div><h2>${tr('profile')}</h2></div><button class="primary" id="create-profile">＋ ${tr('create')}</button></div><div class="chapter-grid" id="profile-grid">${profiles.map(p=>`<article class="chapter-card" data-pid="${esc(p.id)}"><div class="chapter-top"><span class="chapter-emblem">${esc(p.avatar)}</span><div><h3>${esc(p.name)}</h3><div class="ch-sub">${p.xp} XP · ${p.has_pin?'🔒 PIN':''}</div></div></div><div style="display:flex;gap:6px;margin-top:15px"><button class="primary use-profile" data-pid="${esc(p.id)}">${tr('select')} →</button><button class="secondary edit-profile" data-pid="${esc(p.id)}">✎</button><button class="secondary delete-profile" data-pid="${esc(p.id)}">⌫</button></div></article>`).join('')||`<p class="view-lead">${tr('noProfiles')}</p>`}</div><div class="panel" style="margin-top:18px"><h3>${tr('leaderboard')}</h3><div id="leaderboard"></div></div>`;$('#create-profile').onclick=()=>profileForm();$$('.use-profile').forEach(b=>b.onclick=()=>selectProfile(b.dataset.pid));$$('.edit-profile').forEach(b=>b.onclick=()=>profileForm(profiles.find(p=>p.id===b.dataset.pid)));$$('.delete-profile').forEach(b=>b.onclick=()=>deleteProfile(b.dataset.pid));loadLeaderboard();})}
function profileForm(existing){const grid=$('#profile-grid');grid.innerHTML=`<div class="panel" style="grid-column:1/-1"><h3>${existing?tr('edit'):tr('create')}</h3><label style="font-size:11px">${tr('name')}<input id="profile-name" class="answer-input" maxlength="24" value="${esc(existing?.name||'')}"></label><p style="font-size:11px;color:#999">${tr('avatar')}</p><div id="avatar-list" class="achievement-row">${AVATARS.map(a=>`<button class="secondary avatar-choice" data-avatar="${a}" style="font-size:22px;border-color:${existing?.avatar===a?'#aa88ff':''}">${a}</button>`).join('')}</div><label style="display:block;font-size:11px;margin-top:12px">${tr('pin')}<input id="profile-pin" class="answer-input" inputmode="numeric" maxlength="8"></label>${existing?.has_pin?`<label style="font-size:10px"><input type="checkbox" id="remove-pin"> ${L('ui.app.removePin')}</label>`:''}<div style="display:flex;gap:8px;margin-top:14px"><button class="primary" id="save-profile">${tr('save')}</button><button class="secondary" id="cancel-profile">${tr('cancel')}</button></div></div>`;let avatar=existing?.avatar||AVATARS[0];$$('.avatar-choice').forEach(b=>b.onclick=()=>{avatar=b.dataset.avatar;$$('.avatar-choice').forEach(x=>x.style.borderColor=x===b?'#aa88ff':'')});$('#save-profile').onclick=async()=>{const body={name:$('#profile-name').value,avatar,pin:$('#profile-pin').value,lang};let res;if(existing){body.profile_id=existing.id;if(!body.pin)body.pin=$('#remove-pin')?.checked?'REMOVE':'';res=await fetch('/api/profile/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json())}else{res=await fetch('/api/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json())}if(res.error)return toast(res.error);toast(tr('profileSaved'),true);renderProfiles()};$('#cancel-profile').onclick=renderProfiles}
async function selectProfile(id){const p=profiles.find(x=>x.id===id);if(p?.has_pin){const unlocked=await window.CatPinDialog.open({language:p.lang||lang,verify:pin=>window.CatPinDialog.post('/api/select',{profile_id:id,pin})});if(!unlocked)return}else{const result=await window.CatPinDialog.post('/api/select',{profile_id:id,pin:''});if(!result.ok)return toast(result.error||tr('unavailable'))}profileId=id;localStorage.setItem('cpp-adventure-profile',id);appState=await api('/api/state?profile_id='+encodeURIComponent(id));lang=appState.profile.lang||lang;setLangButton();window.CppSplash?.setLanguage(lang);await api('/api/settings',{lang});renderSidebar();renderHome();setView('home');}
async function deleteProfile(id){if(!confirm(tr('confirmDelete')))return;const p=profiles.find(x=>x.id===id);if(p?.has_pin){const removed=await window.CatPinDialog.open({language:p.lang||lang,verify:pin=>window.CatPinDialog.post('/api/profile/delete',{profile_id:id,pin})});if(!removed)return}else{const result=await window.CatPinDialog.post('/api/profile/delete',{profile_id:id,pin:''});if(!result.ok)return toast(result.error||tr('unavailable'))}if(id===profileId){profileId='';localStorage.removeItem('cpp-adventure-profile')}renderProfiles()}
async function exportSave(){const save=await fetch('/api/export?profile_id='+encodeURIComponent(profileId)).then(r=>r.json());download(JSON.stringify(save,null,2),`cpp-adventure-${appState.profile.name}.json`,'application/json')}
async function backupSave(){const r=await api('/api/backup',{});toast(r.error||`${tr('backupDone')} ${r.path||''}`,!r.error)}
function download(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function openSaveTools(){if(!profileId)return toast(L('ui.app.profileRequired'));document.querySelector('#save-modal')?.remove();const layer=document.createElement('div');layer.id='save-modal';layer.className='modal-backdrop';layer.innerHTML=`<section class="save-modal" role="dialog" aria-modal="true" aria-labelledby="save-modal-title"><button class="modal-close" id="save-close" aria-label="${ex('close')}">×</button><span class="eyebrow">💾 ${ex('saved')}</span><h2 id="save-modal-title">${ex('saveTitle')}</h2><p class="save-lead">${ex('saveLead')}</p><div class="save-actions"><button class="save-action" id="save-export"><span>⬇️</span><b>${ex('exportNow')}</b><small>${ex('exportDesc')}</small></button><button class="save-action" id="save-import"><span>📂</span><b>${ex('importNow')}</b><small>${ex('importDesc')}</small></button><button class="save-action" id="save-backup"><span>🛡️</span><b>${ex('makeBackup')}</b><small>${ex('backupDesc')}</small></button></div><div class="save-safety">🔒 ${L('ui.app.savePrivacy')}</div><button class="secondary modal-done" id="save-close-bottom">${ex('close')}</button></section>`;document.body.append(layer);const close=()=>layer.remove();$('#save-close').onclick=close;$('#save-close-bottom').onclick=close;layer.onclick=e=>{if(e.target===layer)close()};$('#save-export').onclick=()=>{exportSave();close()};$('#save-backup').onclick=async()=>{await backupSave();close()};$('#save-import').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const save=JSON.parse(await file.text());if(!confirm(ex('confirmRestore')))return;if(appState?.profile?.pin_protected){const restored=await window.CatPinDialog.open({language:appState.profile.lang||lang,verify:pin=>window.CatPinDialog.post('/api/import',{profile_id:profileId,save,pin})});if(!restored)return}else{const r=await api('/api/import',{save});if(r.error)return toast(r.error)}toast(tr('fileLoaded'),true);close();await boot()}catch{toast(L('ui.app.saveReadError'))}};input.click()}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function boot(){try{await window.CppAdventureI18n.ready;window.CppAdventureI18n.setLanguage(lang);window.CppSplash?.progress(6,'startup');const meta=await api('/api/meta');if(meta.error||!meta.database_ready)throw new Error('local data unavailable');if($('#splash-version'))$('#splash-version').textContent=`v${meta.app_version||'0.4.0'}`;window.CppSplash?.progress(24,'meta');await loadProfiles();window.CppSplash?.progress(55,'profiles');if(profileId&&profiles.some(p=>p.id===profileId)){appState=await api('/api/state?profile_id='+encodeURIComponent(profileId));if(!appState.error){lang=appState.profile.lang||lang;window.CppAdventureI18n.setLanguage(lang);setLangButton();window.CppSplash?.setLanguage(lang);window.CppSplash?.progress(82,'progress');renderSidebar();renderHome();setView('home');document.dispatchEvent(new Event('cpp-adventure-language-changed'));window.CppSplash?.progress(96,'screen');window.CppSplash?.hide();return}}profileId='';localStorage.removeItem('cpp-adventure-profile');setLangButton();window.CppSplash?.setLanguage(lang);renderProfiles();document.dispatchEvent(new Event('cpp-adventure-language-changed'));window.CppSplash?.progress(96,'screen');window.CppSplash?.hide()}catch(error){if(window.CppSplash){window.CppSplash.fail();window.CppSplash.onRetry(()=>{const button=$('#splash-retry');button.disabled=true;boot().finally(()=>{if(button.isConnected)button.disabled=false})})}else toast(tr('unavailable'))}}
