document.addEventListener('DOMContentLoaded',()=>{$('#lang-btn').onclick=changeLang;$('#settings-open').onclick=()=>renderSettings();$('#sound-btn').onclick=()=>toast('Meow! 🐈');$('#top-profile').onclick=renderProfiles;$$('.nav-item').forEach(b=>b.onclick=()=>{if(b.dataset.view!=='labs'&&labTimer){clearInterval(labTimer);labTimer=null}if(!appState)return renderProfiles();if(b.dataset.view==='home'){renderHome();setView('home')}if(b.dataset.view==='map'){renderMap();setView('map')}if(b.dataset.view==='journal'){setView('journal');renderJournal()}if(b.dataset.view==='labs'){setView('labs');renderLabs()}if(b.dataset.view==='quality'){renderQuality();setView('quality')}if(b.dataset.view==='achievements'){renderAchievements();setView('achievements')}if(b.dataset.view==='shop'){renderShop();setView('shop')}if(b.dataset.view==='workshop'){renderWorkshop();setView('workshop')}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();openSaveTools()}if(e.key==='Escape'&&appState)renderProfiles()});boot().then(()=>{const bar=$('.top-actions');if(bar){const b=document.createElement('button');b.className='icon-button';b.dataset.iTitle='saveLoad';b.title=tr('saveLoad');b.textContent='💾';b.onclick=openSaveTools;bar.insertBefore(b,$('#sound-btn'))}})});
// AI key row for Ayarlar: the key itself never reaches the page, only whether it is set and its last 4 characters.
function aiKeyRow(p,status){const ok=status[`${p}_configured`],fromEnv=status[`${p}_key_from_env`];return `<div class="claude-key-row ai-key-row"><b>${aiText(p)}</b><span class="${ok?'status-ok':'status-warn'}">● ${ok?`${aiText('configured')} ${esc(status[`${p}_key_hint`]||'')}`:aiText('missingKey')}</span><small>${aiText('model')}: ${esc(status[`${p}_model`]||'')} · ${fromEnv?aiText(`${p}EnvKey`):aiText('keyStoredLocally')}</small>${fromEnv?'':`<label class="settings-select-label" for="${p}-key">${aiText(`${p}Key`)}</label><div class="claude-key-form"><input id="${p}-key" type="password" autocomplete="off" spellcheck="false" placeholder="${aiText(`${p}KeyPlaceholder`)}"><button class="primary" data-ai-key-save="${p}">${aiText('saveKey')}</button>${ok?`<button class="secondary" data-ai-key-remove="${p}">${aiText('removeKey')}</button>`:''}</div><small>${aiText(`${p}KeyHelp`)}</small>`}</div>`}
// Chapter emblems: one hand-drawn line icon per chapter (sprite in index.html); -1 draws the lock.
function chapterIcon(i){const id=i<0?'lock':`ch-${Math.min(20,Math.max(1,(i|0)+1))}`;const tints=['#ffa45c','#5fe0cf','#a885ff','#ffd58a','#ff8fc7'],tint=i<0?'#8d92a8':tints[(i|0)%tints.length];return `<svg class="ch-ico" viewBox="0 0 24 24" aria-hidden="true" style="--ch-c:${tint}"><use href="#${id==='lock'?'ch-lock':id}"/></svg>`}
// Lesson code samples: lines marked ✗ show a mistake, lines marked ✓ the fix.
function codeMarks(code){return String(code).split('\n').map(line=>{const safe=esc(line);return line.includes('✗')?`<span class="ln-bad">${safe}</span>`:line.includes('✓')?`<span class="ln-good">${safe}</span>`:safe}).join('\n')}
function taskExample(task){if(task.kind==='quiz'||task.kind==='predict'||!task.tests?.length)return'';const t=task.tests.find(x=>String(x.expected??'').trim()!=='')||task.tests[0],input=String(t.input??'').trim(),out=String(t.expected??'');return`<div class="task-example"><span class="task-example-title">${L('motion.exampleTitle')}</span><div class="task-example-grid"><div><small>${L('motion.exampleInput')}</small><pre>${input?esc(input):`<i>${L('motion.exampleNoInput')}</i>`}</pre></div><div><small>${L('motion.exampleOutput')}</small><pre>${out?esc(out):`<i>${L('motion.exampleEmpty')}</i>`}</pre></div></div><p>${L(task.tests.length>1?'motion.exampleMore':'motion.exampleOne')}</p></div>`}
function inlineCodeHtml(text){return esc(text).replace(/`([^`\n]+)`/g,'<code class="inline-code">$1</code>')}
function projectSteps(project){if(!(project.steps||[]).length)return'';const key=`cpp-proj-steps-${profileId}-${project.id}`;let done=[];try{done=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const pct=Math.round(done.length/project.steps.length*100);setTimeout(()=>{$$('.project-step input').forEach(cb=>cb.onchange=()=>{const list=$$('.project-step input').filter(x=>x.checked).map(x=>+x.dataset.idx);try{localStorage.setItem(key,JSON.stringify(list))}catch{}cb.closest('.project-step').classList.toggle('done',cb.checked);const bar=$('.project-steps-bar span');if(bar)bar.style.width=`${Math.round(list.length/project.steps.length*100)}%`})},0);return`<div class="project-steps"><div class="project-steps-head"><b>🧭 ${esc(lang==='ru'?'План работы':'Çalışma planı')}</b><div class="project-steps-bar"><span style="width:${pct}%"></span></div></div><ol>${project.steps.map((st,i)=>`<li class="project-step ${done.includes(i)?'done':''}"><label><input type="checkbox" data-idx="${i}" ${done.includes(i)?'checked':''}><span>${inlineCodeHtml(tx(st))}</span></label></li>`).join('')}</ol></div>`}

